// CodegenRunner — runs generators against a loaded model and writes their files.
//
// The write decision comes from a HASH MANIFEST of what this generator previously
// wrote, not from the <auto-generated/> marker. The marker rule it replaces was wrong
// in both directions: a hand-EDITED generated file keeps its marker, so the one case
// worth protecting was overwritten silently; and a file this generator wrote whose
// template later stopped emitting the marker was refused as though it were somebody's
// hand-written source.
//
// Mirrors codegen-ts's overwrite policy minus the three-way merge, which stays TS-only
// (it needs a full snapshot of prior content plus `git merge-file`). Here the outcome
// for a diverged file is a refusal rather than a merge — see HashManifest.

using MetaObjects.Meta;

namespace MetaObjects.Codegen;

/// <summary>Runs a generator set and writes the emitted files.</summary>
public static class CodegenRunner
{
    /// <summary>Files carrying this marker are owned by codegen and safe to overwrite.</summary>
    public const string GeneratedMarker = "<auto-generated/>";

    public sealed record WriteResult(string Path, string Status);
    public sealed record RunResult(IReadOnlyList<WriteResult> Files, IReadOnlyList<string> Warnings);

    public static RunResult Run(GenConfig config, MetaRoot root, IReadOnlyList<IGenerator> generators)
    {
        var warnings = new List<string>();
        var ctx = new GenContext
        {
            Entities = root.Objects(),
            Root = root,
            Config = config,
            Warn = warnings.Add,
        };

        Directory.CreateDirectory(config.OutDir);
        var results = new List<WriteResult>();
        // Two generators (or a name collision between an entity and a value-object
        // POCO) writing the same path would silently clobber each other; error
        // instead, mirroring codegen-ts's runGen duplicate-path check.
        var emitted = new Dictionary<string, string>(StringComparer.Ordinal);
        var refused = new List<string>();
        // Captured BEFORE any write, because the first write creates the manifest —
        // read it afterwards and every project looks migrated.
        var hadManifest = config.GenStateDir is null || HashManifest.Exists(config.GenStateDir);

        foreach (var generator in generators)
        {
            foreach (var file in generator.Generate(ctx))
            {
                var full = Path.GetFullPath(Path.Combine(config.OutDir, file.Path));
                if (!emitted.TryAdd(full, generator.Name))
                    throw new InvalidOperationException(
                        $"duplicate generated output path \"{file.Path}\" — emitted by both " +
                        $"\"{emitted[full]}\" and \"{generator.Name}\".");
                var status = WriteOne(config, full, file.Path, file.Content, warnings);
                results.Add(new WriteResult(file.Path, status));
                if (status == "refused") refused.Add(file.Path);
            }
        }

        ReportRefusals(refused, hadManifest, warnings);
        return new RunResult(results, warnings);
    }

    /// <summary>
    /// Decide and perform the write for one file.
    /// <para>
    /// With a <see cref="GenConfig.GenStateDir"/> the decision comes from the hash
    /// manifest: identical content is <c>unchanged</c>; a file still hashing to what we
    /// recorded is safe to overwrite; anything else — edited, or never recorded — is
    /// <c>refused</c>. A refusal deliberately does NOT record the current content, since
    /// that would make the file look pristine next run and turn this into a silent
    /// overwrite one run later.
    /// </para>
    /// <para>
    /// With no state dir the legacy marker rule stands, preserving the previous behaviour
    /// (and its status string) for programmatic callers.
    /// </para>
    /// </summary>
    private static string WriteOne(
        GenConfig config, string full, string relPath, string content, List<string> warnings)
    {
        var exists = File.Exists(full);

        if (config.GenStateDir is null)
        {
            if (exists && !File.ReadAllText(full).Contains(GeneratedMarker, StringComparison.Ordinal))
            {
                warnings.Add($"refusing to overwrite hand-written file: {relPath}");
                return "skipped-handwritten";
            }
            WriteFile(full, content);
            // "written" for both a create and an overwrite, preserving the exact status
            // vocabulary this path had before the manifest existed — callers key on it.
            return "written";
        }

        if (!exists)
        {
            WriteFile(full, content);
            HashManifest.Record(config.GenStateDir, relPath, content);
            // "written", not "new": this port's status vocabulary does not distinguish a
            // create from an overwrite, and callers key on it. The manifest ADDS
            // "unchanged" and "refused" without redefining what was already there —
            // renaming these would be an API change unrelated to the defect being fixed.
            return "written";
        }

        var current = File.ReadAllText(full);
        if (current == content)
        {
            // Record it: a first run over already-correct output should leave the file
            // recognisable as ours next time.
            HashManifest.Record(config.GenStateDir, relPath, content);
            return "unchanged";
        }

        if (HashManifest.IsPristine(config.GenStateDir, relPath, current))
        {
            WriteFile(full, content);
            HashManifest.Record(config.GenStateDir, relPath, content);
            return "written";
        }

        return "refused";
    }

    private static void WriteFile(string full, string content)
    {
        var dir = Path.GetDirectoryName(full);
        if (dir is not null) Directory.CreateDirectory(dir);
        File.WriteAllText(full, content);
    }

    /// <summary>
    /// Report refusals ONE of two ways. A project with no manifest predates the manifest
    /// being committed: every refusal shares the same cause and the same one-line fix, so
    /// N per-file warnings would bury the instruction — the hostile-first-contact outcome
    /// that gets a tool switched off. A project that HAS a manifest is refusing because
    /// specific files were edited, and there the per-file naming is the actionable part.
    /// Self-extinguishing: once the manifest is committed, the aggregate never fires again.
    /// </summary>
    private static void ReportRefusals(List<string> refused, bool hadManifest, List<string> warnings)
    {
        if (refused.Count == 0) return;

        if (!hadManifest)
        {
            const int maxNamed = 5;
            var shown = string.Join(", ", refused.Take(maxNamed));
            var more = refused.Count > maxNamed ? $", and {refused.Count - maxNamed} more" : "";
            warnings.Add(
                $"Refused to overwrite {refused.Count} existing file(s), and this project has no " +
                $"codegen hash manifest — so codegen cannot tell your edits from its own stale " +
                $"output, and will not guess. Commit '.gen-state/.hashes.json' and re-run. " +
                $"Files: {shown}{more}.");
            return;
        }

        foreach (var relPath in refused)
        {
            warnings.Add(
                $"Refused to overwrite {relPath}: it has been edited since it was generated, or " +
                $"there is no record of generating it. Move your edits into a non-generated file, " +
                $"or delete it to accept fresh output.");
        }
    }
}
